// Progressive enhancement only. All content (hours, drinks, texts, every language)
// is already in the HTML generated by build.py. This file adds: theme, mobile menu, language menu keys,
// "open now" chips, nav scroll-spy, ticker pause button, drink tabs, lightbox,
// map-on-click, scroll reveal (also marks section headings .visible for their stripe wipe).
(() => {
    document.documentElement.classList.add('js');

    const $ = (s, r = document) => r.querySelector(s);
    const $$ = (s, r = document) => [...r.querySelectorAll(s)];
    const store = {
        get: k => { try { return localStorage.getItem(k); } catch { return null; } },
        set: (k, v) => { try { localStorage.setItem(k, v); } catch { /* ignore */ } }
    };

    // UI strings, opening hours and map URL are provided by build.py in #ui-data
    let ui = {};
    try { ui = JSON.parse($('#ui-data').textContent); } catch { /* use defaults */ }
    const S = ui.strings || {};
    const HOURS = ui.hours || [];

    // ---------- Theme (system default, manual override remembered) ----------
    const darkMq = window.matchMedia('(prefers-color-scheme: dark)');
    const reduceMq = window.matchMedia('(prefers-reduced-motion: reduce)');
    const isDark = () => (document.documentElement.dataset.theme || (darkMq.matches ? 'dark' : 'light')) === 'dark';
    // Browser UI colour follows the sticky header (always dark in this design), else the page
    // background: the static <meta name="theme-color"> tags in the HTML are only the no-JS fallback.
    function syncThemeColor() {
        const metas = $$('meta[name="theme-color"]');
        if (!metas.length) return;
        const bg = getComputedStyle($('.site-header') || document.body).backgroundColor;
        metas.slice(1).forEach(m => m.remove());
        metas[0].removeAttribute('media');
        metas[0].setAttribute('content', bg);
    }
    function renderTheme() {
        syncThemeColor();
        const btn = $('#themeBtn');
        if (!btn) return;
        btn.textContent = isDark() ? '☀' : '☾';
        btn.setAttribute('aria-label', isDark() ? S.themeLight : S.themeDark);
    }
    $('#themeBtn')?.addEventListener('click', () => {
        const next = isDark() ? 'light' : 'dark';
        document.documentElement.dataset.theme = next;
        store.set('theme', next);
        renderTheme();
    });
    darkMq.addEventListener('change', renderTheme);

    // ---------- Mobile menu ----------
    // While the overlay is open everything outside the header is inert, so Tab stays in the menu
    // and the header controls next to it. Opening moves focus to the first menu link (the CSS makes
    // the overlay visible instantly on .open); Escape closes and returns focus to the menu button.
    const header = $('.site-header');
    const nav = $('#nav'), menuBtn = $('#menuBtn');
    let menuOpen = false;
    const pageBehind = () => [...document.body.children].filter(el => el !== header && !el.matches('script, dialog'));
    function setMenu(open) {
        if (!nav || !menuBtn) return;
        menuOpen = open;
        nav.classList.toggle('open', open);
        menuBtn.setAttribute('aria-expanded', String(open));
        menuBtn.setAttribute('aria-label', open ? S.menuClose : S.menuOpen);
        document.body.style.overflow = open ? 'hidden' : '';
        pageBehind().forEach(el => { el.inert = open; });
        if (open) {
            const first = $('a', nav);
            first?.focus();
            if (first && document.activeElement !== first) requestAnimationFrame(() => first.focus());
        }
    }
    menuBtn?.addEventListener('click', () => setMenu(!menuOpen));
    nav?.addEventListener('click', e => { if (menuOpen && e.target.closest('a')) setMenu(false); });
    document.addEventListener('keydown', e => {
        // defaultPrevented: the language menu already used this Escape to close itself
        if (!menuOpen || e.defaultPrevented) return;
        if (e.key === 'Escape') { setMenu(false); menuBtn.focus(); return; }
        if (e.key !== 'Tab') return;
        // Tab / Shift+Tab wrap around inside the header (logo, menu links, theme, language summary and,
        // while it is open, its links, menu button). Closed <details> content has no boxes, so it is skipped.
        const items = $$('a[href], button, summary', header).filter(el => el.getClientRects().length);
        const first = items[0], last = items[items.length - 1];
        if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    });
    // The desktop breakpoint lives only in css/style.css (it hides .menu-btn): close the overlay
    // as soon as the button is gone, e.g. after rotating a tablet or widening the window.
    window.addEventListener('resize', () => {
        if (menuOpen && getComputedStyle(menuBtn).display === 'none') setMenu(false);
    });

    // ---------- Language menu ----------
    // A <details> in the header (build.py lang_switch): opening/closing and the links work without JS.
    // Added here: Escape closes and returns focus to the summary, ArrowDown/ArrowUp (Home/End) move
    // between the links (and open the menu from the summary), a click outside or focus leaving closes it.
    const langBox = $('#langBox');
    if (langBox) {
        const summary = $('summary', langBox);
        const links = $$('.lang-menu a', langBox);
        const close = refocus => {
            if (!langBox.open) return;
            langBox.open = false;
            if (refocus) summary.focus();
        };
        // Escape is caught on the document, not on the menu: Safari and Firefox on macOS do not focus a
        // clicked <summary>, so after a mouse click the key event never reaches #langBox. Capture phase,
        // so this runs before the mobile menu's document listener; preventDefault tells that listener
        // to leave the overlay open (one Escape closes one layer).
        document.addEventListener('keydown', e => {
            if (e.key !== 'Escape' || !langBox.open) return;
            e.preventDefault();
            close(true);
        }, true);
        langBox.addEventListener('keydown', e => {
            const step = { ArrowDown: 1, ArrowUp: -1, Home: 'first', End: 'last' }[e.key];
            if (!step || !links.length) return;
            const i = links.indexOf(document.activeElement);
            if (i < 0 && document.activeElement !== summary) return;
            if (i < 0 && typeof step !== 'number') return; // Home/End keep their meaning on the summary
            e.preventDefault();
            langBox.open = true;
            let next;
            if (step === 'first') next = 0;
            else if (step === 'last') next = links.length - 1;
            else if (i < 0) next = step > 0 ? 0 : links.length - 1;
            else next = (i + step + links.length) % links.length;
            links[next].focus();
        });
        document.addEventListener('click', e => { if (!langBox.contains(e.target)) close(false); });
        langBox.addEventListener('focusout', e => {
            if (e.relatedTarget && !langBox.contains(e.relatedTarget)) close(false);
        });
    }

    // ---------- Header shadow + nav scroll-spy ----------
    // The link whose section crosses the 40% line of the viewport gets aria-current="location".
    const spyLinks = $$('.nav a[href^="#"]')
        .map(a => [a, document.getElementById(a.hash.slice(1))])
        .filter(([, section]) => section);
    let spyCurrent = null;
    function spy() {
        if (!spyLinks.length) return;
        const line = window.innerHeight * 0.4;
        let cur = null;
        for (const [a, section] of spyLinks) {
            const r = section.getBoundingClientRect();
            if (r.top <= line && r.bottom > line) cur = a;
        }
        // At the very bottom the last section may be too short to reach the line: mark it, but only
        // while it is still on screen (the home page ends with the visit strip, which is not in the nav)
        const atBottom = window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 4;
        const [lastLink, lastSection] = spyLinks[spyLinks.length - 1];
        if (atBottom && lastSection.getBoundingClientRect().bottom > 0) cur = lastLink;
        if (cur === spyCurrent) return;
        spyCurrent = cur;
        spyLinks.forEach(([a]) => (a === cur ? a.setAttribute('aria-current', 'location') : a.removeAttribute('aria-current')));
    }
    let ticking = false;
    const onScroll = () => {
        if (header) header.classList.toggle('scrolled', window.scrollY > 10);
        if (ticking) return;
        ticking = true;
        requestAnimationFrame(() => { ticking = false; spy(); });
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    onScroll();

    // ---------- "Open now" badge + highlight today (hours table is static HTML) ----------
    const pad = n => String(n).padStart(2, '0');
    const fmt = h => { h = h % 24; return pad(Math.floor(h)) + ':' + pad(Math.round((h % 1) * 60)); };
    // The bar's clock, not the visitor's: weekday (0 = Sunday, like HOURS) and hour in Europe/Berlin,
    // so someone in London or New York sees whether the bar in Frankfurt is open right now.
    const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    let berlin = null;
    try {
        berlin = new Intl.DateTimeFormat('en-US', { timeZone: 'Europe/Berlin', weekday: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
    } catch { /* no time zone support: fall back to the device clock */ }
    function barClock(date) {
        if (berlin) {
            const p = Object.fromEntries(berlin.formatToParts(date).map(x => [x.type, x.value]));
            const day = WEEKDAYS.indexOf(p.weekday);
            // % 24: some engines write midnight as "24"
            if (day >= 0) return { day, h: (Number(p.hour) % 24) + Number(p.minute) / 60 };
        }
        return { day: date.getDay(), h: date.getHours() + date.getMinutes() / 60 };
    }
    // Same rule as build.py hours_numeric(): [open, close] with close > 24 when it is after midnight,
    // so 01:30 on a Saturday can still belong to Friday's opening hours.
    function isOpen({ day, h }) {
        const today = HOURS[day];
        if (today && h >= today[0] && h < today[1]) return today[1];
        const prev = HOURS[(day + 6) % 7];
        if (prev && prev[1] > 24 && h < prev[1] - 24) return prev[1] - 24;
        return false;
    }
    // Every [data-status] element (hero chip and the one in the hours block) shows the same state.
    function renderStatus() {
        const chips = $$('[data-status]');
        if (!chips.length || !HOURS.length) return;
        const now = barClock(new Date());
        $$('#hours tr').forEach(tr => tr.classList.toggle('today', Number(tr.dataset.d) === now.day));
        const close = isOpen(now);
        const text = close ? `${S.open} · ${S.until} ${fmt(close)}` : S.closed;
        chips.forEach(chip => {
            chip.classList.toggle('open', Boolean(close));
            chip.classList.toggle('closed', !close);
            if (chip.textContent !== text) chip.textContent = text;
        });
    }
    renderStatus();
    setInterval(renderStatus, 60000);

    // ---------- Ticker: moving content needs a pause control (WCAG 2.2.2) ----------
    const ticker = $('.ticker');
    if (ticker && !reduceMq.matches) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'ticker-toggle';
        const label = () => (ticker.classList.contains('is-paused') ? S.tickerPlay : S.tickerPause) || 'Pause';
        btn.setAttribute('aria-label', label());
        btn.addEventListener('click', () => {
            ticker.classList.toggle('is-paused');
            btn.setAttribute('aria-label', label());
        });
        ticker.append(btn);
    }

    // ---------- Drink tabs (all categories are already in the HTML) ----------
    const tabsEl = $('#drinkTabs'), menu = $('#drinks-menu');
    if (tabsEl && menu) {
        const tabs = $$('.drink-tab', tabsEl), panels = $$('.drink-panel', menu);
        tabsEl.hidden = false;
        menu.classList.add('tabs-on');
        panels.forEach(p => p.setAttribute('role', 'tabpanel'));
        const select = (tab, focus) => {
            tabs.forEach(b => {
                const on = b === tab;
                b.setAttribute('aria-selected', String(on));
                b.tabIndex = on ? 0 : -1;
            });
            panels.forEach(p => { p.hidden = p.id !== tab.getAttribute('aria-controls'); });
            if (focus) tab.focus();
        };
        tabs.forEach(b => b.addEventListener('click', () => select(b)));
        tabsEl.addEventListener('keydown', e => {
            if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
            const i = tabs.indexOf(document.activeElement);
            if (i < 0) return;
            select(tabs[(i + (e.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length], true);
        });
        select(tabs[0]);
        // Links like <a href="#drinks-menu" data-drink-tab="tap"> (beer tile) open that category first;
        // the default action then scrolls to the menu. Without JS all panels are visible anyway.
        document.addEventListener('click', e => {
            const a = e.target.closest('a[data-drink-tab]');
            const tab = a && document.getElementById('tab-' + a.dataset.drinkTab);
            if (tab) select(tab);
        });
    }

    // ---------- Lightbox ----------
    const lb = $('#lightbox'), lbImg = $('#lbImg'), items = $$('.gallery-item');
    if (lb) {
        let idx = 0;
        const reduceMotion = reduceMq;
        function show(i, dir = 0) {
            idx = (i + items.length) % items.length;
            const img = $('img', items[idx]);
            lbImg.src = img.currentSrc || img.src;
            lbImg.alt = img.alt;
            if (dir && !reduceMotion.matches && lbImg.animate) lbImg.animate(
                [{ opacity: 0, transform: `translateX(${dir * 48}px)` }, { opacity: 1, transform: 'none' }],
                { duration: 280, easing: 'cubic-bezier(.2,.7,.2,1)' });
        }
        items.forEach((b, i) => b.addEventListener('click', () => { show(i); lb.showModal(); }));
        $('#lbClose').addEventListener('click', () => lb.close());
        $('#lbPrev').addEventListener('click', () => show(idx - 1, -1));
        $('#lbNext').addEventListener('click', () => show(idx + 1, 1));
        lb.addEventListener('click', e => { if (e.target === lb) lb.close(); });
        lb.addEventListener('keydown', e => {
            if (e.key === 'ArrowLeft') show(idx - 1, -1);
            if (e.key === 'ArrowRight') show(idx + 1, 1);
        });
        let touchX = null;
        lb.addEventListener('touchstart', e => { touchX = e.changedTouches[0].clientX; }, { passive: true });
        lb.addEventListener('touchend', e => {
            if (touchX === null) return;
            const dx = e.changedTouches[0].clientX - touchX;
            if (Math.abs(dx) > 50) show(dx < 0 ? idx + 1 : idx - 1, dx < 0 ? 1 : -1);
            touchX = null;
        });
    }

    // ---------- Map (loads only after click, for GDPR) ----------
    const mapBtn = $('#mapBtn');
    if (mapBtn) mapBtn.addEventListener('click', () => {
        const iframe = document.createElement('iframe');
        iframe.src = ui.mapUrl;
        iframe.title = S.mapTitle || 'OpenStreetMap';
        iframe.loading = 'lazy';
        iframe.referrerPolicy = 'no-referrer';
        $('#map').replaceChildren(iframe);
    });

    // ---------- Footer year ----------
    const year = $('#year');
    if (year) year.textContent = new Date().getFullYear();

    // ---------- Scroll reveal (cards slide in; section headings get their stripe wiped in) ----------
    const reveals = $$('.reveal, .section h2, .page-sec .sec-head');
    if ('IntersectionObserver' in window && !reduceMq.matches) {
        const io = new IntersectionObserver(entries => entries.forEach(en => {
            if (en.isIntersecting) { en.target.classList.add('visible'); io.unobserve(en.target); }
        }), { threshold: 0.15 });
        reveals.forEach(el => io.observe(el));
    } else {
        reveals.forEach(el => el.classList.add('visible'));
    }

    renderTheme();
})();
